<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class FacilityMaintenanceController extends Controller{
private function ok(Request $r){$u=$r->user();abort_unless($u->isSuperAdmin()||$u->hasRole('admin')||$u->hasRole('facility_head')||$u->canDo('facility.manage'),403);}
private function number(){return DB::transaction(function(){$y=(int)date('Y');$x=DB::table('facility_sequences')->where('year',$y)->lockForUpdate()->first();if(!$x){DB::table('facility_sequences')->insert(['year'=>$y,'last_number'=>1]);$n=1;}else{$n=$x->last_number+1;DB::table('facility_sequences')->where('year',$y)->update(['last_number'=>$n]);}return 'АХЧ-'.$y.'-'.str_pad($n,5,'0',STR_PAD_LEFT);});}
public function orders(Request $r){$this->ok($r);$rows=DB::table('facility_work_orders as w')->leftJoin('facility_rooms as rm','rm.id','=','w.facility_room_id')->leftJoin('facility_assets as a','a.id','=','w.facility_asset_id')->leftJoin('users as u','u.id','=','w.assigned_to')->select('w.*','rm.number as room_number','a.name as asset_name','u.name as assignee_name')->orderByDesc('w.id')->get();$rooms=DB::table('facility_rooms')->orderBy('number')->get();$assets=DB::table('facility_assets')->where('status','in_use')->orderBy('name')->get();$users=DB::table('users')->orderBy('name')->get();$requests=DB::table('service_requests as x')->join('request_categories as c','c.id','=','x.request_category_id')->where('c.code','maintenance')->whereNotIn('x.status',['resolved','closed','cancelled'])->select('x.*')->get();return view('facility.orders',compact('rows','rooms','assets','users','requests'));}
public function orderStore(Request $r){$this->ok($r);$d=$r->validate(['service_request_id'=>'nullable|exists:service_requests,id','facility_room_id'=>'nullable|exists:facility_rooms,id','facility_asset_id'=>'nullable|exists:facility_assets,id','type'=>'required|in:repair,emergency,maintenance,inspection,installation','priority'=>'required|in:low,normal,high,urgent','title'=>'required|string|max:500','description'=>'nullable|string|max:10000','assigned_to'=>'nullable|exists:users,id','planned_at'=>'nullable|date','due_at'=>'nullable|date']);$id=DB::table('facility_work_orders')->insertGetId($d+['number'=>$this->number(),'status'=>$d['assigned_to']?'assigned':'new','created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);if($d['service_request_id']??null)DB::table('service_requests')->where('id',$d['service_request_id'])->update(['status'=>'in_progress','assigned_to'=>$d['assigned_to']??null,'updated_at'=>now()]);return redirect()->route('facility.orders');}
public function orderUpdate(Request $r,$id){$this->ok($r);$x=DB::table('facility_work_orders')->find($id);abort_if(!$x,404);$d=$r->validate(['status'=>'required|in:new,assigned,in_progress,waiting,completed,cancelled','assigned_to'=>'nullable|exists:users,id','labor_cost'=>'nullable|numeric|min:0','material_cost'=>'nullable|numeric|min:0','result'=>'nullable|string|max:10000']);$up=$d+['updated_at'=>now()];if($d['status']==='in_progress'&&!$x->started_at)$up['started_at']=now();if($d['status']==='completed'&&!$x->completed_at)$up['completed_at']=now();DB::transaction(function()use($id,$x,$d,$up){DB::table('facility_work_orders')->where('id',$id)->update($up);if($x->service_request_id&&$d['status']==='completed')DB::table('service_requests')->where('id',$x->service_request_id)->update(['status'=>'resolved','resolution'=>$d['result']??'Работы выполнены','resolved_at'=>now(),'updated_at'=>now()]);});return back();}
public function plans(Request $r){$this->ok($r);$rows=DB::table('facility_maintenance_plans as p')->leftJoin('facility_assets as a','a.id','=','p.facility_asset_id')->leftJoin('facility_rooms as rm','rm.id','=','p.facility_room_id')->select('p.*','a.name as asset_name','rm.number as room_number')->orderBy('p.next_on')->get();$assets=DB::table('facility_assets')->where('status','in_use')->get();$rooms=DB::table('facility_rooms')->get();$users=DB::table('users')->orderBy('name')->get();return view('facility.plans',compact('rows','assets','rooms','users'));}
public function planStore(Request $r){$this->ok($r);$d=$r->validate(['facility_asset_id'=>'nullable|exists:facility_assets,id','facility_room_id'=>'nullable|exists:facility_rooms,id','title'=>'required|string|max:500','frequency'=>'required|in:weekly,monthly,quarterly,semiannual,annual,custom','interval_days'=>'nullable|integer|min:1','next_on'=>'required|date','responsible_user_id'=>'nullable|exists:users,id','checklist'=>'nullable|string|max:10000']);DB::table('facility_maintenance_plans')->insert($d+['active'=>1,'created_at'=>now(),'updated_at'=>now()]);return back();}
public function inspections(Request $r){$this->ok($r);$rows=DB::table('facility_inspections as i')->leftJoin('facility_buildings as b','b.id','=','i.facility_building_id')->leftJoin('facility_rooms as rm','rm.id','=','i.facility_room_id')->select('i.*','b.name as building_name','rm.number as room_number')->orderByDesc('i.inspected_on')->get();$buildings=DB::table('facility_buildings')->get();$rooms=DB::table('facility_rooms')->get();return view('facility.inspections',compact('rows','buildings','rooms'));}
public function inspectionStore(Request $r){$this->ok($r);$d=$r->validate(['facility_building_id'=>'nullable|exists:facility_buildings,id','facility_room_id'=>'nullable|exists:facility_rooms,id','type'=>'required|in:general,fire,electrical,water,heating,sanitary,safety','inspected_on'=>'required|date','result'=>'required|in:ok,remarks,unsafe','findings'=>'nullable|string|max:10000','actions_required'=>'nullable|string|max:10000','due_on'=>'nullable|date']);DB::table('facility_inspections')->insert($d+['inspector_user_id'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back();}
}